import React, { useState, useEffect } from 'react';
import axios from 'axios';
import StatusStepper from '../components/StatusStepper';
import PackingList from '../components/PackingList';
import { UserIcon, MapPinIcon, PhoneIcon, TruckIcon, ArrowPathIcon } from '@heroicons/react/24/outline';

const API_BASE_URL = 'http://localhost:5000/api';

const Orders = () => {
  const [order, setOrder] = useState(null);
  const [drivers, setDrivers] = useState([]);
  const [selectedDriverId, setSelectedDriverId] = useState('');
  const [loading, setLoading] = useState(true);

  // 1. Fetch Order and Drivers on Load
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [orderRes, staffRes] = await Promise.all([
          axios.get(`${API_BASE_URL}/orders`), // For simplicity, fetching first order
          axios.get(`${API_BASE_URL}/staff`)   // You'll need a simple GET /staff route
        ]);
        
        // Pick the first active order for the dashboard view
        if (orderRes.data.length > 0) {
          setOrder(orderRes.data[0]);
        }
        setDrivers(staffRes.data.filter(s => s.role === 'Driver'));
        setLoading(false);
      } catch (err) {
        console.error("Error fetching data:", err);
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // 2. Advance Status with Driver Assignment Logic
  const advanceStatus = async () => {
    const statuses = ['Pending', 'Packing', 'Out for Delivery', 'Delivered'];
    const currentIdx = statuses.indexOf(order.status);
    const nextStatus = statuses[currentIdx + 1];

    if (currentIdx < statuses.length - 1) {
      // Validation: Must select driver if moving to 'Out for Delivery'
      if (nextStatus === 'Out for Delivery' && !selectedDriverId) {
        alert("Please assign a driver before sending the order out!");
        return;
      }

      try {
        const response = await axios.put(`${API_BASE_URL}/orders/${order._id}/status`, {
          status: nextStatus,
          staffId: nextStatus === 'Out for Delivery' ? selectedDriverId : null
        });
        setOrder(response.data);
      } catch (err) {
        alert("Failed to update status. Check backend connection.");
      }
    }
  };

  // 3. Toggle Packing Checklist in Database
  const toggleItemPacked = async (index) => {
    try {
      const response = await axios.put(`${API_BASE_URL}/orders/${order._id}/pack-item/${index}`);
      setOrder(response.data);
    } catch (err) {
      console.error("Failed to update packing status");
    }
  };

  if (loading) return (
    <div className="flex h-screen items-center justify-center bg-gray-100">
      <ArrowPathIcon className="w-12 h-12 text-blue-600 animate-spin" />
    </div>
  );

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      {/* Sidebar - BigMart Theme */}
      <aside className="w-64 bg-gradient-to-b from-blue-700 to-blue-900 text-white flex flex-col shadow-xl">
        <div className="p-6 text-2xl font-black tracking-wider border-b border-blue-800">
          ONAKO <span className="text-yellow-400">BIGMART</span>
        </div>
        <nav className="mt-6 flex-1">
          <div className="bg-blue-600 border-r-4 border-yellow-400 px-6 py-3 flex items-center space-x-3 cursor-pointer">
            <TruckIcon className="w-5 h-5 text-yellow-400" />
            <span className="font-bold">Active Orders</span>
          </div>
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-8">
        <header className="mb-8 flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Delivery Console</h1>
            <p className="text-gray-500">Local Neighborhood Management System</p>
          </div>
          <div className="text-right">
            <p className="text-xs font-bold text-gray-400 uppercase">Current Session</p>
            <p className="text-sm font-medium text-gray-700">{new Date().toLocaleDateString()}</p>
          </div>
        </header>

        {order ? (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Column 1 & 2: Order & Packing */}
            <div className="lg:col-span-2 space-y-6">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <h2 className="text-2xl font-black text-blue-900">{order.orderID}</h2>
                    <p className="text-sm font-medium text-gray-500">
                      {order.paymentType} • <span className="text-green-600 font-bold">${order.totalAmount.toFixed(2)}</span>
                    </p>
                  </div>
                  <div className="flex flex-col items-end">
                    <span className="px-4 py-1 rounded-full bg-blue-100 text-blue-700 text-xs font-black uppercase tracking-widest">
                      {order.status}
                    </span>
                  </div>
                </div>
                
                <StatusStepper 
                  currentStatus={order.status} 
                  onAdvance={advanceStatus} 
                />
              </div>
              
              <PackingList 
                items={order.items} 
                onTogglePack={toggleItemPacked} 
              />
            </div>

            {/* Column 3: Logistics & Assignment */}
            <div className="space-y-6">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                <h3 className="font-bold text-gray-900 mb-4 border-b pb-2 flex items-center">
                  <MapPinIcon className="w-5 h-5 mr-2 text-blue-600" />
                  Delivery Destination
                </h3>
                <div className="space-y-5">
                  <div className="flex items-start">
                    <UserIcon className="w-5 h-5 text-gray-400 mt-1 mr-3" />
                    <div>
                      <p className="text-sm font-bold text-gray-800">{order.customer.name}</p>
                      <div className="flex items-center text-xs text-gray-500 mt-1">
                        <PhoneIcon className="w-3 h-3 mr-1" /> {order.customer.phoneNumber}
                      </div>
                    </div>
                  </div>
                  
                  <div className="p-3 bg-gray-50 rounded-lg border border-dashed border-gray-300">
                    <p className="text-sm text-gray-700 font-medium leading-relaxed">
                      {order.customer.address.houseNumber}, {order.customer.address.street}
                    </p>
                    <p className="text-xs text-blue-600 mt-2 font-bold uppercase tracking-tight">
                      Landmark: {order.customer.address.landMark}
                    </p>
                  </div>
                </div>

                {/* Driver Assignment Dropdown */}
                {(order.status === "Packing" || order.status === "Out for Delivery") && (
                  <div className="mt-8 pt-6 border-t border-gray-100">
                    <label className="block text-xs font-black text-gray-400 uppercase mb-3 tracking-widest">
                      Assign Delivery Staff
                    </label>
                    <select 
                      value={selectedDriverId}
                      onChange={(e) => setSelectedDriverId(e.target.value)}
                      disabled={order.status === "Out for Delivery" || order.status === "Delivered"}
                      className="w-full bg-gray-50 border-gray-200 rounded-lg py-2.5 text-sm font-medium focus:ring-blue-500 focus:border-blue-500 disabled:opacity-50"
                    >
                      <option value="">Select available driver...</option>
                      {drivers.map(d => (
                        <option key={d._id} value={d._id}>{d.name} ({d.vehicleType})</option>
                      ))}
                    </select>
                    {order.assignedStaff && (
                      <p className="mt-3 text-xs text-green-600 font-bold">
                        ✓ Assigned to: {order.assignedStaff.name}
                      </p>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        ) : (
          <div className="flex h-full items-center justify-center">
            <div className="bg-white px-10 py-12 rounded-xl shadow-sm border border-dashed border-gray-300 text-center max-w-md">
              <h2 className="text-2xl font-bold text-gray-900 mb-2">No active orders found</h2>
              <p className="text-sm text-gray-500">
                There are currently no orders in the system. Once new orders are created, they will appear here automatically.
              </p>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default Orders;
